class Subquery(BaseExpression, Combinable):
    """
    An explicit subquery. It may contain OuterRef() references to fields from
    the outer query which will be resolved when it is applied to that query.
    """
    template = '(%(subquery)s)'
    contains_aggregate = False

    def __init__(self, queryset, output_field=None, **extra):
        self.queryset = queryset
        self.extra = extra
        super().__init__(output_field)

    def _resolve_output_field(self):
        if len(self.queryset.query.select) == 1:
            return self.queryset.query.select[0].field
        return super()._resolve_output_field()

    def copy(self):
        clone = super().copy()
        clone.queryset = self.queryset
        return clone

    def resolve_expression(self, query=None, allow_joins=True, reuse=None, summarize=False, for_save=False):
        clone = super().resolve_expression(query, allow_joins, reuse, summarize, for_save)
        clone.queryset.query.subquery = True
        return clone

    def get_source_expressions(self):
        return [self.queryset]

    def relabeled_clone(self, change_map):
        clone = super().relabeled_clone(change_map)
        clone.queryset = self.queryset.relabeled_clone(change_map)
        return clone

    def as_sql(self, compiler, connection, template=None, query=None, **extra_context):
        if query is None:
            query = self.queryset.query
        query.subquery = True
        subquery_sql, sql_params = query.get_compiler(connection=connection).as_sql()
        template = template or self.template
        context = {
            **self.extra,
            **extra_context,
            'subquery': subquery_sql,
        }
        return template % context, sql_params

    def as_sqlite(self, compiler, connection, **extra_context):
        template = None
        if connection.features.allow_sliced_subqueries:
            # SQLite doesn't support slicing in subqueries, so we need to
            # limit the subquery manually.
            if self.queryset.query.low_mark or self.queryset.query.high_mark is not None:
                template = '(SELECT * FROM (%(subquery)s) %(slicing)s)'
                slicing = 'LIMIT %d OFFSET %d' % (
                    self.queryset.query.high_mark - self.queryset.query.low_mark,
                    self.queryset.query.low_mark,
                )
                extra_context['slicing'] = slicing
        return super().as_sql(compiler, connection, template=template, **extra_context)
